input.new_string:
/**
 * Megabytes charged to one tenant: each file's size rounded up to whole
 * megabytes, then summed. Rounding per file is what the upload guard books, so
 * this is the figure the recount has to reproduce. SQLite integer division
 * gives the round-up: `(bytes + MB - 1) / MB` is `ceil(bytes / MB)` for whole
 * byte counts (1048576 is one megabyte).
 */
export async function sumStorageMb(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({
      value: sql<number | null>`sum((${attachments.sizeBytes} + 1048575) / 1048576)`,
    })
    .from(attachments)
    .where(orgPredicate(attachments.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

